/// credit, deletes the attendance, and frees the seat. Admin/Receptionist only.
/// </summary>
[HttpDelete("booking/{bookingId}")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> RemoveBooking(string bookingId)
{
    var success = await _schedulingService.RemoveAttendanceAsync(bookingId);
    if (!success) return NotFound();
    return Ok(new { message = "Attendee removed from class." });
}

[HttpPatch("booking/{bookingId}/flags")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor,Instructor")]
public async Task<IActionResult> UpdateBookingFlags(string bookingId, [FromBody] FlagUpdateRequest request)
{
    var success = await _schedulingService.UpdateAttendanceFlagsAsync(bookingId, request.IsFreeClass, request.CountsTowardsCommission);
    if (!success) return NotFound();
    return Ok(new { message = "Flags updated." });
}

/// <summary>
/// Collect a studio payment for a specific booking. Creates a linked
/// Invoice + Payment and updates the Attendance's AmountPaid / AmountDueAtStudio.
/// Used by the calendar roster and client-profile "Collect" buttons.
/// </summary>
[HttpPost("booking/{attendanceId}/collect-payment")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> CollectBookingPayment(
    string attendanceId, [FromBody] CollectBookingPaymentRequest request)
{
    try
    {
        var result = await _schedulingService.CollectStudioPaymentAsync(
            attendanceId, request.Amount, request.PaymentMethod,
            request.Notes, _invoiceService, request.AttendingSeats,
            request.PaymentSplits);
        return Ok(result);
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>
/// SPM-79 — Admin reschedule of an existing booking to a different session.
/// Moves the BOOKED attendance onto the target session, adjusts both sessions'
/// CurrentBookings, promotes the old session's waitlist and emails the customer.
/// Bypasses the customer cancellation/reschedule policy caps.
/// </summary>
[HttpPost("booking/{attendanceId}/reschedule")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> RescheduleBooking(
    string attendanceId, [FromBody] AdminRescheduleBookingRequest request)
{
    try
    {
        var result = await _schedulingService.AdminRescheduleBookingAsync(attendanceId, request.NewSessionId);
        return Ok(result);
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>
/// Returns upcoming sessions for a given class blueprint, with availability info.
/// Used by the POS session picker modal when a CLASS tile is clicked.
/// </summary>
[HttpGet("sessions-for-blueprint/{blueprintId}")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> GetSessionsForBlueprint(string blueprintId)
{
    var now = DateTime.UtcNow;
    var sessions = await _schedulingService.GetSessionsAsync(now, now.AddDays(14));
    var matching = sessions
        .Where(s => s.ClassBlueprintId == blueprintId
            && s.Status == "SCHEDULED"
            && string.IsNullOrWhiteSpace(s.BlockedReason))
        .OrderBy(s => s.StartTime)
        .Take(30)
        .Select(s => new
        {
            id = s.Id,
            className = s.ClassName,
            instructorName = s.InstructorName,
            startTime = s.StartTime,
            endTime = s.EndTime,
            format = s.Format,
            capacity = s.Capacity,
            currentBookings = s.CurrentBookings,
            spotsLeft = Math.Max(0, s.Capacity - s.CurrentBookings),
            dropInPrice = s.DropInPrice ?? 0m,
        })
        .ToList();
    return Ok(matching);
}

/// <summary>
/// Atomic POS walk-in class checkout: validates capacity, creates Attendance
/// (WALK_IN, BOOKED), creates linked Invoice + Payment, increments session
/// bookings. Used when a receptionist sells a class at POS.
/// </summary>
[HttpPost("walk-in-checkout")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> WalkInCheckout([FromBody] WalkInCheckoutRequest request)
{
    try
    {
        var result = await _schedulingService.WalkInCheckoutAsync(
            request.SessionId, request.ClientId, request.Amount,
            request.PaymentMethod, request.Notes, _invoiceService,
            request.PackageInstanceId, request.ReferralDiscountPct);
        return Ok(result);
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

[HttpDelete("session/{id}")]
[Authorize(Roles = "Admin,Manager")]
public async Task<IActionResult> CancelSession(string id)
{
    var success = await _schedulingService.CancelSessionAsync(id);
    if (!success) return NotFound(new { message = "Session not found." });
    return Ok(new { message = "Session cancelled and credits refunded where applicable." });
}

