startReassign() {
  const row = document.getElementById('cdpInstructorRow');
  if (!row || !this._sessionDetail) return;
  const c = this._sessionDetail;
  const staffList = this._getStaffList().filter(s => s.isActive !== false);
  const opts = '<option value="">— No instructor —</option>' + staffList.map(s =>
    `<option value="${s.id}" ${s.id === c.instructorId ? 'selected' : ''}>${this._esc(s.name)}</option>`).join('');
  row.innerHTML = `<span class="dp-icon">👤</span>
    <select class="dp-inst-select" id="cdpReassignSelect">${opts}</select>
    <button class="dp-inst-save" onclick="ClassDetailPanel.commitReassign()">Save</button>
    <button class="dp-inst-cancel" onclick="ClassDetailPanel.refresh()">Cancel</button>`;
},

commitReassign() {
  const sel = document.getElementById('cdpReassignSelect');
  if (!sel) return;
  const newId = sel.value || null;
  const newName = newId ? (sel.options[sel.selectedIndex]?.text || '') : '';
  if (newId === (this._sessionDetail?.instructorId || null)) { this.refresh(); return; }
  this._patchSession({ instructorId: newId, instructorName: newName }, 'Instructor reassigned');
},

/* ── Mini-POS checkout (per attendee, inline) ─────────────── */
showCollectPayment(attendanceId, amountDue, clientId, clientName, quantity = 1, bookingStatus = '') {
  const s = this._sessionDetail || {};
  const seats = Math.max(1, Number(quantity) || 1);
  const standardPer = Number(s.dropInPrice ?? 0);
  const perSeat = standardPer > 0 ? standardPer : (seats > 0 ? (Number(amountDue || 0) / seats) : 0);
  this._mpos = {
    attendanceId, clientId, clientName,
    bookingStatus: (bookingStatus || '').toUpperCase(),
    seats,                    // booked seats (drives the split row)
    bookedSeats: seats,
    attendingSeats: seats,    // how many actually showed → what we charge
    perSeat,
    format: (s.format || 'GROUP').toUpperCase(),
    dropInPrice: amountDue || 0,
    chargeDropIn: true,     // false → settle the class with a package credit
    lines: [],              // product lines (merch/packages)
    promo: null,
    products: null,
    paySplit: false,        // true → operator is splitting the total across ≥2 methods
    _paySeq: 0,             // monotonic id for extra tender line inputs
    _pickList: [],
  };
  document.getElementById('cdpCpAttendanceId').value = attendanceId;
  document.getElementById('mposClient').textContent = `${clientName || 'Client'} · ${s.className || 'Class'}`;
  document.getElementById('mposDiscAmt').value = 0;
  document.getElementById('mposDiscType').value = 'FIXED';
  document.getElementById('mposPromo').value = '';
  document.getElementById('mposPromoHint').textContent = '';
  document.getElementById('mposNote').value = '';
  // Flag the note as required when this attendee's amount due differs from
  // the class's standard drop-in price (the API rejects a custom amount
  // without a reason). Standard price comes from the loaded class detail.
  // Note is required only when the amount isn't a clean per-seat multiple
  // (a genuinely custom charge) — NOT merely because a multi-seat booking
  // totals more than one seat.
  this._mposNoteRequired = perSeat > 0 && Number(amountDue || 0) !== perSeat * seats;
  const req = document.getElementById('mposNoteReq');
  if (req) req.style.display = this._mposNoteRequired ? '' : 'none';
  // Offer "split into separate people" only for multi-seat unpaid bookings.
  const splitRow = document.getElementById('mposSplitRow');
  if (splitRow) {
    splitRow.style.display = seats >= 2 ? '' : 'none';
    const seatsEl = document.getElementById('mposSplitSeats');
    if (seatsEl) seatsEl.textContent = String(seats);
  }
  // "Attending" adjuster for multi-seat bookings where only some showed up.
  const attendRow = document.getElementById('mposAttendRow');
  if (attendRow) {
    attendRow.style.display = seats >= 2 ? '' : 'none';
    const ai = document.getElementById('mposAttending');
    if (ai) { ai.max = String(seats); ai.value = String(seats); }
    const ao = document.getElementById('mposAttendOf');
    if (ao) ao.textContent = ' · ' + seats + ' booked';
  }
  document.getElementById('mposPicker').style.display = 'none';
  document.getElementById('mposCredits').style.display = 'none';
  this._mposResetPay();
  this._mposRenderCart();
  document.getElementById('cdpCollectModal').classList.add('open');
  this._mposLoadCredits(clientId);
},

async _mposLoadCredits(clientId) {
  const el = document.getElementById('mposCredits');
  try {
    const pkgs = await fetch(`${_CDP_API}/api/wallet/client/${clientId}`,
