    const chips = [chip('Group', g, '#2BB7A3'), chip('Mat', m, '#63b3ed'), chip('Private', pv, '#F4923C')].filter(Boolean).join('');
    const infoIc = '<svg class="b-ic" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>';
    if (chips) {
