},

_mposFmt(n) { return (Math.round(n || 0)).toLocaleString() + ' ₫'; },

_mposRenderCart() {
  const m = this._mpos; const esc = this._esc.bind(this);
  const cls = esc((this._sessionDetail && this._sessionDetail.className) || 'Class');
  const personIc = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
  let html = '';
  if (m.chargeDropIn) {
    const note = m.attendingSeats > 1 ? `<div class="mpos-line-note">${m.attendingSeats} × ${this._mposFmt(m.perSeat)}</div>` : '';
    html += `<div class="mpos-line">
      <div class="mpos-line-ic">${personIc}</div>
      <div class="mpos-line-main"><div class="mpos-line-title">Drop-in class</div><div class="mpos-line-sub">${cls}</div>
        <button class="mpos-swap" onclick="ClassDetailPanel.mposSwapClass(false)">Use package credit instead →</button></div>
      <div class="mpos-line-right"><div class="mpos-line-amt">${this._mposFmt(m.dropInPrice)}</div>${note}</div></div>`;
  } else {
    html += `<div class="mpos-line">
      <div class="mpos-line-ic">${personIc}</div>
      <div class="mpos-line-main"><div class="mpos-line-title">Package credit${m.attendingSeats > 1 ? ` (${m.attendingSeats} people)` : ''}</div><div class="mpos-line-sub">${cls}</div>
        <button class="mpos-swap" onclick="ClassDetailPanel.mposSwapClass(true)">← Charge drop-in instead</button></div>
      <div class="mpos-line-right"><div class="mpos-line-amt credit">${m.attendingSeats} credit${m.attendingSeats === 1 ? '' : 's'}</div></div></div>`;
  }
  m.lines.forEach((l, i) => {
    html += `<div class="mpos-line">
