  try {
    // 1) Product invoice (merch/packages) — manual + promo discount apportioned to products.
    if (m.lines.length > 0) {
      const lines = m.lines.map(l => ({ productId: l.productId, variantId: l.variantId ?? null, description: l.variantLabel ? `${l.name} — ${l.variantLabel}` : l.name, quantity: l.qty, unitPrice: l.unitPrice, lineDiscount: 0 }));
      const prodDisc = this._mposDiscount(m._prodSub);
      const inv = await fetch(`${_CDP_API}/api/invoice`, {
        method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + tok },
        body: JSON.stringify({ clientId: m.clientId, lines, discountAmount: prodDisc }),
      }).then(r => r.json());
      if (inv?.id) {
        const net = Math.max(0, m._prodSub - prodDisc);
        if (net > 0) {
          const payBody = { amountPaid: net, paymentMethod: method, paymentDate: new Date().toISOString() };
          if (split && split.product && split.product.length) payBody.paymentSplits = split.product;
          await fetch(`${_CDP_API}/api/invoice/${inv.id}/payment`, {
            method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + tok },
            body: JSON.stringify(payBody),
          });
        }
      }
    }
    // 2) Settle the class — package credit or drop-in money. A note is
    // required by the API whenever the charged amount differs from the
    // class's standard price (e.g. covering a second walk-in on one bill).
    const note = (document.getElementById('mposNote').value || '').trim() || null;
    // Only send attendingSeats when it's actually fewer than booked — shrinks the
    // booking to who showed and charges/deducts just those seats.
    const attending = (m.attendingSeats && m.attendingSeats < m.bookedSeats) ? m.attendingSeats : null;
    const classBody = m.chargeDropIn
      ? { amount: m.dropInPrice, paymentMethod: method, notes: note, attendingSeats: attending }
      : { amount: 0, paymentMethod: 'PACKAGE_CREDIT', notes: note, attendingSeats: attending };
    // Attach the class's share of the split tenders (drop-in money only).
    if (split && m.chargeDropIn && split.class && split.class.length) classBody.paymentSplits = split.class;
    const cr = await fetch(`${_CDP_API}/api/scheduling/booking/${m.attendanceId}/collect-payment`, {
      method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + tok },
      body: JSON.stringify(classBody),
    });
    if (!cr.ok) { const e = await cr.clone().json().catch(() => ({})); throw new Error(e.detail || e.message || 'Could not settle the class'); }
    // 3) Check in — but NOT for penalty statuses. A late cancel / no-show can still
    // forfeit a credit or pay a fee (step 2), yet the person did NOT attend, so we
    // must preserve that status instead of flipping it to "Arrived".
    const isPenalty = m.bookingStatus === 'LATE_CANCEL' || m.bookingStatus === 'NO_SHOW';
    if (!isPenalty) {
      await fetch(`${_CDP_API}/api/scheduling/booking/${m.attendanceId}/status`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + tok },
        body: JSON.stringify({ status: 'ARRIVED' }),
      });
    }
    window.showToast?.(isPenalty ? 'Credit charged — status kept' : 'Checked out & checked in', 'success');
    this.closeCollectModal();
    if (this._afterAttendanceUpdate && this._sessionId) await this._afterAttendanceUpdate(this._sessionId);
    if (this._sessionId) await this._refreshRoster(this._sessionId);
  } catch (e) {
    window.showToast?.(e.message || 'Checkout failed', 'error');
  } finally {
    btn.disabled = false; btn.textContent = '✅ Complete & check in';
  }
},

