namespace SoulPilates.API.Controllers;

/// <summary>
/// P3-S09 — instructor self-service portal API.
///
/// <para>
/// Role-gated at the controller level: every endpoint here requires
/// a valid JWT with <c>Role = "Instructor"</c>. Admin / Owner users
/// hitting these endpoints will receive HTTP 403, even though their
/// tokens are otherwise valid for the platform.
/// </para>
///
/// <para>
/// <b>Admin impersonation</b>: Admin and SuperAdmin users may pass
/// <c>?viewAs={staffId}</c> on any endpoint to impersonate an
/// instructor. This is enforced server-side — Instructor-role tokens
/// always resolve their own <c>staff_id</c> JWT claim regardless of
/// the query parameter.
/// </para>
/// </summary>
[ApiController]
[Authorize(Roles = "Instructor,HeadInstructor,Admin,SuperAdmin,Owner")]
[Route("api/instructor")]
public class InstructorController : ControllerBase
{
    private readonly IInstructorService _instructorService;
    private readonly ISchedulingService _schedulingService;
    private readonly IClientService _clientService;
    private readonly IWaitlistService _waitlistService;

    public InstructorController(
        IInstructorService instructorService,
        ISchedulingService schedulingService,
        IClientService clientService,

