}

/// <summary>
/// SPM-83 — Instructor quick-add: add an EXISTING client to one of the
/// instructor's OWN sessions, always UNPAID. Reuses the same service mechanics
/// as the admin add-student flow (creates a BOOKED, WALK_IN attendance with no
/// payment / invoice / credit deduction). Admin impersonation skips the
/// ownership check; instructors may only add to sessions they teach.
/// </summary>
[HttpPost("session/{id}/add-student")]
public async Task<IActionResult> AddStudentToMySession(string id, [FromBody] InstructorAddStudentRequest request)
{
    var staffId = ResolveStaffId();
    if (string.IsNullOrWhiteSpace(staffId))
        return NotFound(new { profileLinked = false });

    // Ownership check (admins impersonating bypass this)
    var session = await _schedulingService.GetSessionByIdAsync(id);
    if (session == null)
        return NotFound(new { message = "Session not found." });
    if (!IsAdminRole() && session.InstructorId != staffId)
        return StatusCode(403, new { message = "You can only add clients to your own sessions." });

    try
    {
        var attendance = await _schedulingService.AdminAddStudentAsync(
            id, request.ClientId, request.ClientName, request.ClientPhone, request.Quantity);
        return Ok(attendance);
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>
/// Remove an attendee from one of MY sessions. Ownership-checked: the session
/// must be taught by the caller (admins impersonating bypass), and the booking
/// must genuinely be on that session's roster. Frees the seat / refunds credit.
/// </summary>
[HttpDelete("session/{sessionId}/booking/{attendanceId}")]
public async Task<IActionResult> RemoveMyAttendee(string sessionId, string attendanceId)
{
    var staffId = ResolveStaffId();
    if (string.IsNullOrWhiteSpace(staffId))
        return NotFound(new { profileLinked = false });

    var session = await _schedulingService.GetSessionByIdAsync(sessionId);
    if (session == null)
        return NotFound(new { message = "Session not found." });
    if (!IsAdminRole() && session.InstructorId != staffId)
        return StatusCode(403, new { message = "You can only manage your own sessions." });

    var ok = await _schedulingService.RemoveAttendanceFromSessionAsync(sessionId, attendanceId);
    if (!ok) return NotFound(new { message = "Attendee not found on this class." });
    return Ok(new { message = "Attendee removed from class." });
}

/// <summary>
/// Read-only, instructor-safe client profile (contact / health / visit history,
/// NO financial data) shown when the instructor taps an attendee.
/// </summary>
[HttpGet("attendee/{clientId}/profile")]
public async Task<IActionResult> GetAttendeeProfile(string clientId)
{
    var profile = await _schedulingService.GetAttendeeProfileAsync(clientId);
    if (profile == null) return NotFound(new { message = "Client not found." });
    return Ok(profile);
}

