[HttpGet("me")]
public async Task<IActionResult> GetMe()
{
    var staffId = ResolveStaffId();
    var profile = await _instructorService.GetProfileAsync(staffId);
    if (profile == null)
        return NotFound(new { profileLinked = false });
    return Ok(profile);
}

