/** The ordered bills money is actually collected against — the product
 *  invoice net, then the class amount — each rounded to whole đồng. Shared
 *  by the split total, the allocation, and mposComplete so they reconcile. */
_mposBills() {
  const m = this._mpos; if (!m) return [];
  const prodSub = m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  const productNet = Math.round(Math.max(0, prodSub - this._mposDiscount(prodSub)));
  const classAmount = Math.round(m.chargeDropIn ? m.dropInPrice : 0);
  const bills = [];
  if (m.lines.length > 0 && productNet > 0) bills.push({ key: 'product', amount: productNet });
  if (classAmount > 0) bills.push({ key: 'class', amount: classAmount });
  return bills;
},

input.new_string:
/** Gross/discount/net for the class charge alone. Mirrors the product-line
 *  discount pattern (`_mposDiscount(prodSub)` below) so a discount typed
 *  into the mini-POS discount field actually reaches the class charge —
 *  previously it only ever reached the product-invoice line, so a
 *  class-only sale (no merch/package lines) silently dropped the discount
 *  and charged the full undiscounted amount (SP-INV-260826-0002). */
_mposClassAmounts() {
  const m = this._mpos; if (!m) return { gross: 0, discount: 0, net: 0 };
  const gross = Math.round(m.chargeDropIn ? (m.dropInPrice || 0) : 0);
  const discount = m.chargeDropIn ? Math.round(this._mposDiscount(gross)) : 0;
  return { gross, discount, net: Math.max(0, gross - discount) };
},

/** The ordered bills money is actually collected against — the product
 *  invoice net, then the class amount (net of any discount) — each rounded
 *  to whole đồng. Shared by the split total, the allocation, and
 *  mposComplete so they reconcile. */
_mposBills() {
  const m = this._mpos; if (!m) return [];
  const prodSub = m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  const productNet = Math.round(Math.max(0, prodSub - this._mposDiscount(prodSub)));
  const classAmount = this._mposClassAmounts().net;
  const bills = [];
  if (m.lines.length > 0 && productNet > 0) bills.push({ key: 'product', amount: productNet });
  if (classAmount > 0) bills.push({ key: 'class', amount: classAmount });
  return bills;
},

