using SoulPilates.Core.Interfaces;
using System.Security.Claims;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public class AuthController : ControllerBase
{
    private readonly IAuthService _authService;

    public AuthController(IAuthService authService)
    {
        _authService = authService;
    }

    [HttpPost("login")]
    [EnableRateLimiting("auth-login")] // P4-S12: 10 req / 60s per IP — protects against credential stuffing.
    public async Task<IActionResult> Login([FromBody] LoginRequest request)
    {
        var result = await _authService.AuthenticateAsync(request);
        if (result == null) return Unauthorized(new { message = "Invalid email or password" });

        return Ok(result);
    }

    /// <summary>
    /// Forced first-login password change. Requires a valid JWT (the user has
    /// already authenticated with their admin-issued initial password). On
    /// success, clears the MustChangePassword flag so subsequent logins proceed
    /// normally to the dashboard.
    /// </summary>
    [HttpPost("change-password")]
    [Authorize]
    public async Task<IActionResult> ChangePassword([FromBody] ForceChangePasswordRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.NewPassword) || request.NewPassword.Length < 8)
            return BadRequest(new { message = "Password must be at least 8 characters." });

        if (request.NewPassword != request.ConfirmPassword)
            return BadRequest(new { message = "Passwords do not match." });

        var userId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (string.IsNullOrWhiteSpace(userId))
            return Unauthorized();

        var ok = await _authService.ChangePasswordAsync(userId, request.NewPassword);
        if (!ok) return NotFound(new { message = "User not found." });

        return Ok(new { message = "Password updated successfully." });
    }
}

