[HttpGet]
[AllowAnonymous]
public async Task<IActionResult> Get([FromQuery] DateTime start, [FromQuery] DateTime end)
{
    var sessions = await _schedulingService.GetSessionsAsync(start, end);

    // SPM-91 — unauthenticated callers must not see private sessions. Mirror
    // GetPublicScheduleAsync's keep-legacy/missing-true semantics: exclude only
    // sessions explicitly marked IsPublic == false. Authenticated staff (admin
    // calendar) still receive private sessions.
    if (User.Identity?.IsAuthenticated != true)
    {
        sessions = sessions.Where(s => s.IsPublic);
    }

    return Ok(sessions);
}

[HttpPost("session")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> CreateSession([FromBody] CalendarSession session)
{
    var created = await _schedulingService.CreateSessionAsync(session);
    return Ok(created);
}

[HttpPost("book")]
[Authorize]
public async Task<IActionResult> Book([FromQuery] string sessionId, [FromQuery] string clientId)
{
    bool authSuccess = await _walletService.DeductCreditAsync(clientId, "GROUP", "temp_booking");
    if (!authSuccess) return BadRequest(new { message = "Insufficient active credits for this format." });

    try {
        var attendance = await _schedulingService.BookClientAsync(sessionId, clientId, null);
        return Ok(attendance);
    } catch (Exception ex) {
        return BadRequest(new { message = ex.Message });
    }
}

