// Update the Attendance's payment tracking fields atomically.
// A discount is money forgiven, not still outstanding, so it must retire
// the due balance exactly like the cash collected does — otherwise a
// fully-discounted booking is left showing a phantom balance (and skips
// the BOGO credit grant below, which gates on newAmountDue <= 0).
// `remainingDue` (the fallback when AmountDueAtStudio was never
// snapshotted) is already net-of-discount from the check above, so only
// `amount` comes off it; `AmountDueAtStudio` holds the original GROSS
// snapshot and needs both `amount` and `discount` subtracted.
var newAmountPaid = previouslyPaid + amount;
var newAmountDue = attendance.AmountDueAtStudio is decimal dueSnapshot
    ? Math.Max(0, dueSnapshot - amount - discount)
    : Math.Max(0, remainingDue - amount);

