/// <summary>P3-S09b — read login status for the staff-form's "Login access" section.</summary>
[HttpGet("{id}/login")]
public async Task<IActionResult> GetLogin(string id)
{
    var status = await _staffService.GetLoginStatusAsync(id);
    return Ok(status);
}

/// <summary>P3-S09b — create a new instructor user + link in one step.</summary>
[HttpPost("{id}/login")]
public async Task<IActionResult> CreateLogin(string id, [FromBody] SoulPilates.Core.DTOs.CreateStaffLoginRequest request)
{
    var result = await _staffService.CreateLoginAsync(id, request);
    if (result is null)
    {
        // Ambiguous failure surface — staff doesn't exist, email
        // is taken, or input was blank. The frontend reads the
        // controller's preceding GET response and shows the
        // appropriate hint, so a generic 400 here is sufficient.
        return BadRequest(new
        {
            message = "Could not create login. The email may already be in use, or the staff member no longer exists.",
        });
    }
    return Ok(result);
}

/// <summary>P3-S09b — link an existing orphan instructor user to this staff.</summary>
[HttpPut("{id}/login")]
public async Task<IActionResult> LinkLogin(string id, [FromBody] SoulPilates.Core.DTOs.LinkStaffLoginRequest request)
{
    var result = await _staffService.LinkExistingUserAsync(id, request);
    if (result is null)
    {
        return BadRequest(new
        {
            message = "No unlinked instructor user with that email was found. The user may already be linked to another staff member.",
        });
    }
    return Ok(result);
}

/// <summary>P3-S09b — unlink the user currently attached to this staff.</summary>
[HttpDelete("{id}/login")]
public async Task<IActionResult> UnlinkLogin(string id)
{
    var removed = await _staffService.UnlinkLoginAsync(id);
    if (!removed)
        return NotFound(new { message = "No linked user found for this staff member." });
    return Ok(new { message = "Login unlinked successfully." });
}

